import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const i="/bzygq/assets/quesion_imgs_image_1766291398802_0_1766291398808_642.BgZ_xlxy.png",l="/bzygq/assets/quesion_imgs_image_1766291399766_1_1766291399770_324.CJwFPAdS.png",s="/bzygq/assets/quesion_imgs_image_1766291400069_2_1766291400075_233.yeQnaCnU.png",n="/bzygq/assets/quesion_imgs_image_1766291400480_3_1766291400482_145.BAu5b1AZ.png",_="/bzygq/assets/quesion_imgs_image_1766291400744_4_1766291400748_84.CSRw9cX7.png",h="/bzygq/assets/quesion_imgs_image_1766291401037_5_1766291401045_764.B2-pUBZz.png",p="/bzygq/assets/quesion_imgs_image_1766291401456_6_1766291401462_573.CqlUqrI7.png",g="/bzygq/assets/quesion_imgs_image_1766291401796_7_1766291401805_331.bnJL1MzW.png",P=JSON.parse('{"title":"2、森林、树与二叉树的转换","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/数据结构/6、树和二叉树/2、森林、树与二叉树的转换.md","filePath":"科技岗专业课/数据结构/6、树和二叉树/2、森林、树与二叉树的转换.md","lastUpdated":1788883925000}'),d={name:"科技岗专业课/数据结构/6、树和二叉树/2、森林、树与二叉树的转换.md"};function c(b,t,u,m,q,f){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_2、森林、树与二叉树的转换" tabindex="-1">2、森林、树与二叉树的转换 <a class="header-anchor" href="#_2、森林、树与二叉树的转换" aria-label="Permalink to &quot;2、森林、树与二叉树的转换&quot;">​</a></h1><p><strong>森林、树与二叉树的转换</strong></p><table tabindex="0"><thead><tr><th>【原创声明】大家好，我是say，是这篇文章的原创作者！985硕士毕业，应届进入某大厂后道心破碎，社招上岸多家855半垄断央企，因为自己淋过雨，希望帮大家撑把伞，帮助更多同学找到不内卷、能够好好生活的央国企，已帮助1000+同学上岸央国企，需要连联系学长的加微信：wx_hxsay</th></tr></thead></table><h2 id="什么是森林" tabindex="-1">什么是森林？ <a class="header-anchor" href="#什么是森林" aria-label="Permalink to &quot;什么是森林？&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>在数据结构中，<strong>森林是由多个互不相交的树组成的集合</strong>，每棵树具有以下特征：</p><ol><li><strong>节点关系</strong>：每个节点（除根节点外）有且仅有一个父节点，可以有零或多个子节点。</li><li><strong>无环结构</strong>：树中不存在环路，任意两个节点之间只有一条唯一路径。</li><li><strong>独立性</strong>：森林中的树彼此独立，无共享节点或边。</li></ol><p>类比一下，森林就像一片由多棵独立树木组成的自然森林，每棵树自成体系，彼此之间没有根系或枝叶的交织。</p><h2 id="树、森林与二叉树的转换" tabindex="-1">树、森林与二叉树的转换 <a class="header-anchor" href="#树、森林与二叉树的转换" aria-label="Permalink to &quot;树、森林与二叉树的转换&quot;">​</a></h2><h2 id="树-→-二叉树" tabindex="-1">树 → 二叉树 <a class="header-anchor" href="#树-→-二叉树" aria-label="Permalink to &quot;树 → 二叉树&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p><strong>核心思想</strong>：通过“左孩子右兄弟”表示法，将多叉树转换为仅含左、右子节点的二叉树。</p><p><strong>转换步骤</strong>：</p><p><img src="'+s+'" alt=""></p><ol><li>**加线：**在树中，将所有兄弟节点通过水平连线连接起来，这一步骤的目的是构建节点间的横向关系，以便后续转换。</li><li>**去线：**仅保留父节点与第一个子节点之间的连线，删除父节点与其他子节点的直接连接，通过这一操作，突出了第一个子节点作为 “左孩子” 的特殊地位。</li><li>**层次调整：**以根节点为轴，将整个结构顺时针旋转 45°，经过旋转，二叉树的层次结构更加清晰，便于理解与后续操作。</li></ol><h2 id="森林-→-二叉树" tabindex="-1">森林 → 二叉树 <a class="header-anchor" href="#森林-→-二叉树" aria-label="Permalink to &quot;森林 → 二叉树&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p><strong>核心思想</strong>：将森林中的每棵树分别转换为二叉树，再通过右指针链接成链状结构。</p><p><strong>转换步骤</strong>：</p><p><img src="'+_+'" alt=""></p><ol><li><strong>单树转换</strong>：将每棵树按“树→二叉树”规则转换。</li></ol><p><img src="'+h+'" alt=""></p><ol><li><strong>链接成链</strong>：将第二棵二叉树的根节点作为第一棵根节点的右孩子，第三棵作为第二棵的右孩子，依此类推。</li></ol><p><strong>意义</strong>：通过右指针串联多棵树，实现森林的线性化表示。</p><h2 id="二叉树-→-树-森林" tabindex="-1">二叉树 → 树/森林 <a class="header-anchor" href="#二叉树-→-树-森林" aria-label="Permalink to &quot;二叉树 → 树/森林&quot;">​</a></h2><p><img src="'+p+'" alt=""></p><p><strong>核心思想</strong>：逆向操作，将二叉树的右指针还原为兄弟关系。</p><p><strong>转换步骤（以二叉树→树为例）</strong>：</p><p><img src="'+g+'" alt=""></p><ol><li>加线：如果某节点存在左孩子，那么该节点的右孩子以及所有右后代节点，都将作为该节点的子节点。通过这一步，恢复了树结构中节点间的多叉分支关系。</li><li>去线：删除所有右孩子与原父节点之间的连线，使得节点关系更加符合树的结构定义。</li><li>层次调整：对节点进行重新排列，恢复树原本自然的层次结构，使树的形态更加直观。</li></ol><h2 id="树和森林的遍历原理" tabindex="-1">树和森林的遍历原理 <a class="header-anchor" href="#树和森林的遍历原理" aria-label="Permalink to &quot;树和森林的遍历原理&quot;">​</a></h2><h2 id="树的深度优先遍历" tabindex="-1">树的深度优先遍历 <a class="header-anchor" href="#树的深度优先遍历" aria-label="Permalink to &quot;树的深度优先遍历&quot;">​</a></h2><h3 id="先序遍历树流程" tabindex="-1">先序遍历树流程 <a class="header-anchor" href="#先序遍历树流程" aria-label="Permalink to &quot;先序遍历树流程&quot;">​</a></h3><p><strong>核心思想</strong>：先访问根节点，再从左到右递归遍历子树。</p><p><strong>步骤</strong>：</p><ol><li>访问根节点。</li><li>对根节点的子节点（从左到右顺序）依次递归执行先序遍历。</li></ol><p><strong>示例</strong>： | Plain Text树结构：A/ \\B C/ | \\D E F先序遍历结果：A → B → C → D → E → F | | --- |</p><p><strong>代码实现（递归）</strong>：</p><table tabindex="0"><thead><tr><th>Plain Textdef pre_order_tree(root):if root is None:returnprint(root.value)for child in root.children: # 从左到右遍历子节点pre_order_tree(child)</th></tr></thead></table><h3 id="中序遍历树流程" tabindex="-1">中序遍历树流程 <a class="header-anchor" href="#中序遍历树流程" aria-label="Permalink to &quot;中序遍历树流程&quot;">​</a></h3><p><strong>说明</strong>：普通树没有严格的中序遍历定义，但可通过转换后的二叉树间接实现。</p><p><strong>规则</strong>（基于二叉树转换逻辑）：</p><ol><li>递归遍历左子树（原树的第一个子节点）。</li><li>访问根节点。</li><li>递归遍历右子树（原树的兄弟节点）。</li></ol><p><strong>示例</strong>：</p><table tabindex="0"><thead><tr><th>Plain Text原树结构：A/ \\B C转换后的二叉树：A/B\\C中序遍历结果：B → A → C</th></tr></thead></table><h2 id="森林的先序遍历" tabindex="-1">森林的先序遍历 <a class="header-anchor" href="#森林的先序遍历" aria-label="Permalink to &quot;森林的先序遍历&quot;">​</a></h2><h3 id="森林先序遍历流程" tabindex="-1">森林先序遍历流程 <a class="header-anchor" href="#森林先序遍历流程" aria-label="Permalink to &quot;森林先序遍历流程&quot;">​</a></h3><p><strong>核心思想</strong>：依次对森林中的每棵树执行先序遍历。</p><p><strong>步骤</strong>：</p><ol><li>从第一棵树开始，执行树的先序遍历。</li><li>完成当前树后，继续对下一棵树执行先序遍历。</li></ol><p><strong>示例</strong>： | Plain Text森林结构：树1：A-B-C | 树2：D-E先序遍历结果：A → B → C → D → E | | --- |</p><p><strong>代码实现（递归）</strong>：</p><table tabindex="0"><thead><tr><th>Plain Textdef pre_order_forest(forest):for tree_root in forest:pre_order_tree(tree_root) # 直接调用树的先序遍历函数</th></tr></thead></table><h3 id="森林中序遍历流程" tabindex="-1">森林中序遍历流程 <a class="header-anchor" href="#森林中序遍历流程" aria-label="Permalink to &quot;森林中序遍历流程&quot;">​</a></h3><p><strong>说明</strong>：与树的中序遍历类似，需基于转换后的二叉树实现。</p><p><strong>规则</strong>：</p><ol><li>将森林转换为二叉树（右链连接各树根）。</li><li>对转换后的二叉树执行中序遍历。</li></ol><p><strong>示例</strong>： | Plain Text原森林：树1：A | 树2：B-C转换后的二叉树：A\\B/C中序遍历结果：A → C → B | | --- |</p><p><strong>代码实现</strong>：</p><table tabindex="0"><thead><tr><th>Plain Textdef in_order_forest(forest):# 将森林转换为二叉树（此处假设已实现）converted_bst = convert_forest_to_bst(forest)in_order_tree(converted_bst) # 调用树的中序遍历函数</th></tr></thead></table><h2 id="树和森林的广度优先遍历" tabindex="-1">树和森林的广度优先遍历 <a class="header-anchor" href="#树和森林的广度优先遍历" aria-label="Permalink to &quot;树和森林的广度优先遍历&quot;">​</a></h2><p><strong>核心思想</strong>：按层级逐层访问节点，从左到右、从上到下扫描。</p><h1 id="树的广度优先遍历" tabindex="-1">树的广度优先遍历 <a class="header-anchor" href="#树的广度优先遍历" aria-label="Permalink to &quot;树的广度优先遍历&quot;">​</a></h1><p><strong>步骤</strong>：</p><ol><li>初始化队列，将根节点入队。</li><li>循环执行：</li></ol><ul><li>弹出队首节点并访问。</li><li>将该节点的所有子节点（从左到右）入队。</li></ul><p><strong>示例</strong>：</p><table tabindex="0"><thead><tr><th>Plain Text树结构：A/ \\B C/ \\D E广度优先遍历结果：A → B → C → D → E</th></tr></thead></table><p><strong>代码实现（队列）</strong>：</p><table tabindex="0"><thead><tr><th>Plain Textfrom collections import dequedef bfs_tree(root):queue = deque([root])while queue:node = queue.popleft()print(node.value)queue.extend(node.children) # 从左到右入队</th></tr></thead></table><h1 id="森林的广度优先遍历" tabindex="-1">森林的广度优先遍历 <a class="header-anchor" href="#森林的广度优先遍历" aria-label="Permalink to &quot;森林的广度优先遍历&quot;">​</a></h1><p><strong>步骤</strong>：</p><ol><li>初始化队列，依次将所有树的根节点入队。</li><li>循环执行：</li></ol><ul><li>弹出队首节点并访问。</li><li>若该节点属于某棵树，将其所有子节点入队。</li></ul><p><strong>示例</strong>： | Plain Text森林结构：树1：A-B | 树2：C-D广度优先遍历结果：A → C → B → D | | --- |</p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2>',76)])])}const A=a(d,[["render",c]]);export{P as __pageData,A as default};
